mapper.select:

SELECT *
FROM tb_user_coupon
WHERE user_id=#{user}
AND id>#{after}
ORDER BY id
LIMIT #{limit}

mapper.update:

UPDATE tb_user_coupon
SET state='LOCKED', lock_order_id=#{orderId}, lock_token=#{token}, version=version+1
WHERE id=#{id}
AND state='AVAILABLE'
AND version=#{version}


UPDATE tb_user_coupon
SET state=#{state}, lock_order_id=NULL, lock_token=NULL, version=version+1
WHERE id=#{id}


UPDATE tb_user_coupon
SET state='EXPIRED', version=version+1
WHERE state='AVAILABLE'
AND valid_until_ms<=#{now}
LIMIT #{limit}
